import React, { useEffect, useMemo, useState } from "react";
import useServices from "../hooks/useServices";
import {
  BOOKINGS_KEY, DATA_EVENT, makeId, readJson, SERVICES_KEY, writeJson,
} from "../utils/storage";
import "./Dashboard.css";

const statuses = ["Pending", "Contacted", "Confirmed", "In Service", "Delivered", "Cancelled"];
const blankService = { name: "", description: "", price: "", image: "" };

export default function AdminDashboard() {
  const services = useServices();
  const [bookings, setBookings] = useState([]);
  const [tab, setTab] = useState("bookings");
  const [form, setForm] = useState(blankService);
  const [editingId, setEditingId] = useState(null);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const refresh = () => setBookings(readJson(BOOKINGS_KEY, []).sort((a, b) => new Date(b.bookedAt) - new Date(a.bookedAt)));
    refresh();
    const sync = (event) => (!event.key || event.key === BOOKINGS_KEY) && refresh();
    window.addEventListener("storage", sync);
    window.addEventListener(DATA_EVENT, sync);
    return () => {
      window.removeEventListener("storage", sync);
      window.removeEventListener(DATA_EVENT, sync);
    };
  }, []);

  const counts = useMemo(() => ({
    total: bookings.length,
    pending: bookings.filter((item) => (item.status || "Pending") === "Pending").length,
    delivered: bookings.filter((item) => item.status === "Delivered").length,
  }), [bookings]);

  const updateStatus = (id, status) => {
    writeJson(BOOKINGS_KEY, readJson(BOOKINGS_KEY, []).map((item) =>
      item.id === id ? { ...item, status, updatedAt: new Date().toISOString() } : item
    ));
  };

  const contactCustomer = (booking) => {
    updateStatus(booking.id, "Contacted");
    window.location.href = `tel:${booking.phone}`;
  };

  const saveService = (event) => {
    event.preventDefault();
    if (!form.name.trim() || !form.description.trim() || Number(form.price) <= 0) {
      setMessage("Name, description, and a valid price are required.");
      return;
    }
    const item = {
      ...form,
      name: form.name.trim(),
      description: form.description.trim(),
      price: Number(form.price),
      image: form.image.trim() || "https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=600&q=80",
    };
    const updated = editingId
      ? services.map((service) => service.id === editingId ? { ...item, id: editingId } : service)
      : [...services, { ...item, id: makeId() }];
    writeJson(SERVICES_KEY, updated);
    setForm(blankService);
    setEditingId(null);
    setMessage(editingId ? "Service updated." : "Service added.");
  };

  const editService = (service) => {
    setEditingId(service.id);
    setForm({ name: service.name, description: service.description, price: service.price, image: service.image });
    setMessage("");
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const deleteService = (service) => {
    if (!window.confirm(`Delete "${service.name}"? Existing bookings will not be removed.`)) return;
    writeJson(SERVICES_KEY, services.filter((item) => item.id !== service.id));
    if (editingId === service.id) {
      setEditingId(null);
      setForm(blankService);
    }
    setMessage("Service deleted.");
  };

  return (
    <section className="dashboard-page section">
      <div className="container">
        <div className="dashboard-head">
          <div><span className="eyebrow">Admin Portal</span><h1>Service Management</h1><p>Manage customer jobs and the services shown on the website.</p></div>
        </div>
        <div className="admin-tabs">
          <button className={tab === "bookings" ? "active" : ""} onClick={() => setTab("bookings")}>Customer Bookings</button>
          <button className={tab === "services" ? "active" : ""} onClick={() => setTab("services")}>Service CRUD</button>
        </div>

        {tab === "bookings" ? <>
          <div className="stat-grid">
            <div><strong>{counts.total}</strong><span>Total bookings</span></div>
            <div><strong>{counts.pending}</strong><span>Pending</span></div>
            <div><strong>{counts.delivered}</strong><span>Delivered</span></div>
          </div>
          {bookings.length ? <div className="admin-table-wrap"><table className="admin-table">
            <thead><tr><th>Customer</th><th>Bike &amp; Service</th><th>Date</th><th>Contact</th><th>Status</th></tr></thead>
            <tbody>{bookings.map((booking) => <tr key={booking.id}>
              <td><strong>{booking.name}</strong><small>{booking.phone}<br />{booking.userEmail}</small></td>
              <td><strong>{booking.serviceName}</strong><small>{booking.bikeBrand} {booking.bikeModel}<br />{booking.regNumber}</small></td>
              <td>{new Date(`${booking.date}T00:00:00`).toLocaleDateString("en-IN")}</td>
              <td><button className="table-action contact" onClick={() => contactCustomer(booking)}>Call User</button></td>
              <td><select value={booking.status || "Pending"} onChange={(event) => updateStatus(booking.id, event.target.value)}>{statuses.map((status) => <option key={status}>{status}</option>)}</select></td>
            </tr>)}</tbody>
          </table></div> : <div className="empty-state"><h2>No bookings received</h2><p>New customer requests will appear here automatically.</p></div>}
        </> : <div className="service-admin-grid">
          <form className="service-editor" onSubmit={saveService}>
            <h2>{editingId ? "Edit Service" : "Add New Service"}</h2>
            <label>Service Name<input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label>
            <label>Description<textarea rows="4" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} /></label>
            <label>Price (₹)<input type="number" min="1" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></label>
            <label>Image URL<input type="url" value={form.image} onChange={(e) => setForm({ ...form, image: e.target.value })} /></label>
            {message && <p className="form-message">{message}</p>}
            <div className="editor-actions">
              <button className="btn btn-primary" type="submit">{editingId ? "Update Service" : "Add Service"}</button>
              {editingId && <button className="btn btn-dark" type="button" onClick={() => { setEditingId(null); setForm(blankService); setMessage(""); }}>Cancel</button>}
            </div>
          </form>
          <div className="managed-services">
            <h2>Available Services ({services.length})</h2>
            {services.map((service) => <article key={service.id}>
              <img src={service.image} alt="" />
              <div><h3>{service.name}</h3><p>₹{service.price}</p></div>
              <button className="table-action" onClick={() => editService(service)}>Edit</button>
              <button className="table-action danger" onClick={() => deleteService(service)}>Delete</button>
            </article>)}
          </div>
        </div>}
      </div>
    </section>
  );
}
